#!/usr/bin/env bash
# d137-ts-defs-r1 攻方腿：把 samples/ 里的钩子输入逐条喂给钩子，每条一行 name=<样本> hook=<钩子> exit=<退出码> expected=<照被判定义原文该得的退出码>。
# 用法：bash feed.sh <输出目录>（整条经 task-server 交；tools/rerun.sh 起它）。钩子与样本写字面路径（共用约束「不做」一节：草稿脚本里起的每一条写字面路径）。
# 每条样本放进自己的进程组（setsid --wait），超时 120 秒由 timeout 对那一组发信号；检出记录写进输出目录，不进工作根的检出记录。
set -u
OUT="$1"
mkdir -p "$OUT"
DET="$OUT/detections.jsonl"
setsid --wait timeout -k 5 120 env AGENT_HOOK_DETECTIONS="$DET" bash /home/fy5090/code/singlefs/.claude/hooks/heavy-test-guard.sh < /home/fy5090/code/singlefs/research/prompts/d137-ts-defs-r1-opus-model/samples/h0-light-crash-main.json > "$OUT/h0-light-crash-main.out" 2>&1; echo "name=h0-light-crash-main hook=heavy-test-guard exit=$? expected=0"
setsid --wait timeout -k 5 120 env AGENT_HOOK_DETECTIONS="$DET" bash /home/fy5090/code/singlefs/.claude/hooks/heavy-test-guard.sh < /home/fy5090/code/singlefs/research/prompts/d137-ts-defs-r1-opus-model/samples/h1-light-crash-in-copy.json > "$OUT/h1-light-crash-in-copy.out" 2>&1; echo "name=h1-light-crash-in-copy hook=heavy-test-guard exit=$? expected=0"
setsid --wait timeout -k 5 120 env AGENT_HOOK_DETECTIONS="$DET" bash /home/fy5090/code/singlefs/.claude/hooks/heavy-test-guard.sh < /home/fy5090/code/singlefs/research/prompts/d137-ts-defs-r1-opus-model/samples/h2-light-formal-in-copy.json > "$OUT/h2-light-formal-in-copy.out" 2>&1; echo "name=h2-light-formal-in-copy hook=heavy-test-guard exit=$? expected=0"
setsid --wait timeout -k 5 120 env AGENT_HOOK_DETECTIONS="$DET" bash /home/fy5090/code/singlefs/.claude/hooks/heavy-test-guard.sh < /home/fy5090/code/singlefs/research/prompts/d137-ts-defs-r1-opus-model/samples/h3-rerun-builds-and-runs-probe.json > "$OUT/h3-rerun-builds-and-runs-probe.out" 2>&1; echo "name=h3-rerun-builds-and-runs-probe hook=heavy-test-guard exit=$? expected=0"
setsid --wait timeout -k 5 120 env AGENT_HOOK_DETECTIONS="$DET" bash /home/fy5090/code/singlefs/.claude/hooks/heavy-test-guard.sh < /home/fy5090/code/singlefs/research/prompts/d137-ts-defs-r1-opus-model/samples/h3b-rerun-feeds-hook-by-variable.json > "$OUT/h3b-rerun-feeds-hook-by-variable.out" 2>&1; echo "name=h3b-rerun-feeds-hook-by-variable hook=heavy-test-guard exit=$? expected=0"
setsid --wait timeout -k 5 120 env AGENT_HOOK_DETECTIONS="$DET" bash /home/fy5090/code/singlefs/.claude/hooks/heavy-test-guard.sh < /home/fy5090/code/singlefs/research/prompts/d137-ts-defs-r1-opus-model/samples/h4-kb-scribe-precheck-as-written.json > "$OUT/h4-kb-scribe-precheck-as-written.out" 2>&1; echo "name=h4-kb-scribe-precheck-as-written hook=heavy-test-guard exit=$? expected=0"
setsid --wait timeout -k 5 120 env AGENT_HOOK_DETECTIONS="$DET" bash /home/fy5090/code/singlefs/.claude/hooks/heavy-test-guard.sh < /home/fy5090/code/singlefs/research/prompts/d137-ts-defs-r1-opus-model/samples/h5-writer-combined-clippy-build.json > "$OUT/h5-writer-combined-clippy-build.out" 2>&1; echo "name=h5-writer-combined-clippy-build hook=heavy-test-guard exit=$? expected=0"
setsid --wait timeout -k 5 120 env AGENT_HOOK_DETECTIONS="$DET" bash /home/fy5090/code/singlefs/.claude/hooks/write-guard.sh < /home/fy5090/code/singlefs/research/prompts/d137-ts-defs-r1-opus-model/samples/w1-kb-scribe-precheck-in-scope.json > "$OUT/w1-kb-scribe-precheck-in-scope.out" 2>&1; echo "name=w1-kb-scribe-precheck-in-scope hook=write-guard exit=$? expected=0"
setsid --wait timeout -k 5 120 env AGENT_HOOK_DETECTIONS="$DET" bash /home/fy5090/code/singlefs/.claude/hooks/write-guard.sh < /home/fy5090/code/singlefs/research/prompts/d137-ts-defs-r1-opus-model/samples/w2-kb-scribe-precheck-out-of-scope.json > "$OUT/w2-kb-scribe-precheck-out-of-scope.out" 2>&1; echo "name=w2-kb-scribe-precheck-out-of-scope hook=write-guard exit=$? expected=2"
setsid --wait timeout -k 5 120 env AGENT_HOOK_DETECTIONS="$DET" bash -c 'bash /home/fy5090/code/singlefs/.claude/hooks/write-guard.sh < /nonexistent-d137-precheck.json' > "$OUT/w3-precheck-input-missing.out" 2>&1; echo "name=w3-precheck-input-missing hook=write-guard exit=$? expected=not-2"
echo "name=feed_done samples=10"
